"""Original acid-base emergencies; calculations and competing physiological diagnoses."""
from qbank_authoring import question,ref
rows=[]
AB=ref('Physiological approach to assessment of acid-base disturbances','https://doi.org/10.1056/NEJMra1003327')
DK=ref('International consensus on hyperglycaemic crises: 2024','https://pmc.ncbi.nlm.nih.gov/articles/PMC11343900/')
BI=ref('BICARICU-2 randomized trial: 2025','https://jamanetwork.com/journals/jama/fullarticle/2840824')
def add(stem,answer,wrong,title,principle,mechanism,action,checks,table,refs,style='clinical_scenario'):
    rows.append(question(stem,answer,wrong,title,principle,mechanism,action,checks,table,refs,style))

add('An ICU patient has pH 7.25, PaCO2 25 mmHg and bicarbonate 11 mmol/L. Which interpretation best fits?', 'Metabolic acidosis with approximately appropriate respiratory compensation',[
 ('Metabolic acidosis with additional respiratory acidosis','Winter prediction is about 24.5 ± 2 mmHg; measured CO2 is not above this range.'),('Metabolic acidosis with additional respiratory alkalosis','CO2 is within the expected compensatory range.'),('Primary respiratory alkalosis with renal compensation alone','The acidemic pH and severe bicarbonate reduction indicate primary metabolic acidosis.')],
 'Compare measured CO2 with the expected response','**Winter prediction is approximately 1.5 × bicarbonate + 8, with a 2 mmHg range.**',['At bicarbonate eleven, the expected PaCO2 is approximately twenty-four to twenty-seven.','Compensation does not itself explain the cause of the metabolic disorder.'],'**Investigate the metabolic acid source and monitor ventilation.**',['Calculate the anion gap with albumin context.','A later rise in CO2 can signal fatigue even if its absolute value remains below forty.'],[['Bicarbonate','11'],['Expected CO2','24.5 ± 2'],['Measured CO2','25']],[DK])

add('A patient with bicarbonate 10 mmol/L has PaCO2 40 mmHg and pH 7.02. Which additional disorder is present?', 'Respiratory acidosis in addition to metabolic acidosis',[
 ('Appropriate compensatory hyperventilation','Expected CO2 is near twenty-three, substantially below forty.'),('Primary metabolic alkalosis','Bicarbonate is low and the patient is acidemic.'),('Additional respiratory alkalosis','CO2 exceeds rather than falls below the metabolic-acidosis prediction.')],
 'A normal-range CO2 can be inappropriately high','**Interpret PaCO2 relative to the metabolic disturbance.**',['The expected ventilatory response is lost when respiratory drive or mechanical capacity fails.','Sedation, exhaustion, airway disease and CNS injury are possible contributors.'],'**Assess airway and ventilation while treating the metabolic cause.**',['Intubation can worsen acidemia if pre-intubation minute ventilation is not supported.','Use blood gas trends rather than oxygen saturation alone.'],[['Expected CO2','About 23 ± 2'],['Measured CO2','40'],['Meaning','Superimposed ventilatory failure']],[DK])

add('Sodium is 140, chloride 100 and bicarbonate 12 mmol/L. Excluding potassium, what is the anion gap?', '28 mmol/L',[
 ('12 mmol/L','This is bicarbonate rather than the calculated gap.'),('40 mmol/L','This omits bicarbonate subtraction.'),('152 mmol/L','This adds bicarbonate rather than subtracting the measured anions.')],
 'Use a consistent anion-gap convention','**The potassium-excluded gap is sodium minus chloride minus bicarbonate.**',['Here one hundred forty minus one hundred minus twelve equals twenty-eight.','The laboratory reference range depends on methodology.'],'**Account for albumin before excluding an unmeasured-anion process.**',['Identify lactate, ketones, kidney dysfunction and potential toxins.','A gap is a clue to mechanism rather than a toxin identification test.'],[['Sodium','140'],['Chloride plus bicarbonate','112'],['Gap','28']],[DK])

add('An ICU patient has an anion gap of 10 mmol/L and albumin 2 g/dL. Using 2.5 mmol/L per 1 g/dL albumin below 4, what is the corrected gap?', '15 mmol/L',[
 ('5 mmol/L','Low albumin conceals rather than augments the measured gap; correction is upward.'),('10 mmol/L','This ignores the reduction in the major unmeasured anion.'),('20 mmol/L','This overcorrects for the two-gram albumin deficit with the stated factor.')],
 'Hypoalbuminemia can conceal a gap acidosis','**Corrected gap is measured gap + 2.5 × (4 − albumin in g/dL).**',['Ten plus five equals fifteen.','The correction is an approximation and depends on the selected normal albumin/gap convention.'],'**Interpret the corrected result with measured lactate and ketones.**',['Do not use a normal uncorrected gap to exclude organic acid accumulation.','Trend the same calculation during treatment.'],[['Albumin deficit','2 g/dL'],['Added correction','5 mmol/L'],['Corrected gap','15 mmol/L']],[AB])

add('A patient has sodium 140, chloride 92 and bicarbonate 18 mmol/L, with normal albumin. Using normal gap 12 and bicarbonate 24, what does the delta ratio suggest?', 'High-gap metabolic acidosis with an additional metabolic alkalosis',[
 ('Pure normal-gap metabolic acidosis','The measured gap is thirty, clearly elevated.'),('High-gap acidosis with an additional normal-gap acidosis','That typically produces a lower, not high, delta ratio.'),('Pure chronic respiratory acidosis','The low bicarbonate and large unmeasured-anion gap do not fit.')],
 'Compare the rise in gap with the fall in bicarbonate','**The delta ratio is (30 − 12)/(24 − 18) = 3.**',['A rise in gap substantially greater than the bicarbonate fall suggests an accompanying alkalinizing process.','Ratios are heuristic: prior chemistry, timing and treatment can alter interpretation.'],'**Look for vomiting, diuretics or a high baseline bicarbonate.**',['Do not replace serial clinical assessment with a ratio threshold.','Use the complete blood gas to assess respiratory components.'],[['Gap rise','18'],['Bicarbonate fall','6'],['Ratio','3; suggests accompanying alkalosis in context']],[AB])

add('A patient develops bicarbonate 16 mmol/L after a large chloride-rich crystalloid load; lactate and ketones are normal and the anion gap is normal. Which mechanism best fits?', 'Hyperchloremic metabolic acidosis from reduced strong-ion difference',[
 ('New accumulation of ketoacids','Normal ketones and a normal gap after chloride loading favor another mechanism.'),('Primary hypoventilation','This primarily raises CO2; the described chloride/bicarbonate change is metabolic.'),('Chloride-depletion alkalosis','Chloride loading produces the opposite acid-base tendency.')],
 'Not every ICU acidosis reflects tissue hypoxia','**A chloride increase relative to sodium can lower bicarbonate without adding unmeasured anions.**',['Kidney dysfunction can prolong the disturbance.','Clinical assessment is still needed to exclude concurrent hypoperfusion.'],'**Reassess ongoing fluids and the underlying indication for resuscitation.**',['Avoid giving more volume simply to normalize bicarbonate.','Track chloride, renal function and gas exchange.'],[['Gap','Usually normal'],['Chloride','Relatively increased'],['Cause','Iatrogenic fluid contribution']],[AB])

add('An adult has bicarbonate 40 mmol/L, hypokalemia and ongoing nasogastric losses. Urine chloride is 8 mmol/L before saline or diuretics. Which classification is most useful?', 'Chloride-responsive metabolic alkalosis',[
 ('Chloride-resistant mineralocorticoid excess','Low untreated urine chloride and gastric losses favor depletion.'),('Compensated chronic respiratory alkalosis','That produces reduced, not markedly elevated, bicarbonate.'),('Distal renal tubular acidosis','This is a metabolic acidosis, not the described alkalosis.')],
 'Separate generation from maintenance of alkalosis','**Gastric hydrogen/chloride loss generates alkalosis; volume and potassium depletion maintain it.**',['Low urine chloride supports renal chloride conservation.','Recent diuretic exposure or saline changes the interpretation.'],'**Correct the loss, potassium and chloride deficit as the volume state permits.**',['Use potassium chloride rather than an alkalinizing potassium salt when suitable.','Volume-overloaded patients require a different correction strategy.'],[['Urine chloride','Low before treatment'],['Typical cause','Gastric loss'],['Treatment principle','Cause plus chloride/potassium replacement']],[AB])

add('A ventilated patient with prolonged hypercapnia has PaCO2 rapidly normalized but bicarbonate remains 38 mmol/L and pH becomes 7.57. Which diagnosis best explains this?', 'Post-hypercapnic metabolic alkalosis',[
 ('New isolated respiratory acidosis','CO2 was lowered; the persisting bicarbonate now causes alkalemia.'),('New lactic acidosis','That lowers bicarbonate and does not explain this pattern.'),('Appropriate acute renal compensation for respiratory alkalosis','Renal bicarbonate excretion has not yet caught up with the rapid change.')],
 'Renal adaptation resolves more slowly than ventilator changes','**Bicarbonate retained during chronic hypercapnia can persist after rapid CO2 correction.**',['Volume, chloride and potassium deficits can sustain the alkalosis.','An acceptable CO2 target depends on baseline disease and current physiology.'],'**Review ventilation and correct maintainers of alkalosis.**',['Avoid chasing a normal CO2 irrespective of pH.','Acetazolamide can lower bicarbonate in selected cases but is not a universal weaning cure.'],[['Before','Chronic CO2 retention with bicarbonate retention'],['After rapid correction','Residual metabolic alkalosis'],['Review','Ventilation and electrolyte/volume state']],[AB])

add('Which physiological effect can make sodium bicarbonate problematic when ventilation is severely limited?', 'Generation of additional CO2 that requires effective elimination',[
 ('Direct removal of CO2 through the kidneys within minutes','The immediate buffering reaction produces CO2 rather than eliminating it.'),('Permanent intracellular potassium removal','Bicarbonate is not a method of potassium removal from the body.'),('Selective correction of the cause of lactate production','It can change extracellular pH without correcting oxygen delivery or metabolism.')],
 'Buffering is not equivalent to reversing the cause','**Bicarbonate buffering generates carbon dioxide.**',['CO2 retention can worsen intracellular and respiratory acid burden when ventilation is insufficient.','Sodium load, ionized-calcium changes and volume effects also matter.'],'**Treat the cause and evaluate ventilation before choosing buffering.**',['Bicarbonate can have specific indications; these depend on the disorder.','A rising pH alone does not prove improved tissue perfusion.'],[['Buffer reaction','Additional CO2'],['Requirement','Adequate elimination'],['Other concerns','Sodium, volume and ionized calcium']],[BI],style='direct')

add('In BICARICU-2, which conclusion best describes sodium bicarbonate for the studied severe metabolic acidemia with stage 2–3 AKI?', 'It did not significantly reduce 90-day mortality, although kidney replacement therapy was used less often',[
 ('It established a mortality benefit for all causes of ICU acidosis','The trial did not show that outcome and excluded several acid-base/toxicological groups.'),('It proved bicarbonate should replace urgent dialysis for refractory complications','The trial does not remove established urgent support indications.'),('It demonstrated no change in either mortality or kidney replacement use','Kidney replacement use differed even though mortality did not significantly improve.')],
 'Keep primary and secondary outcomes distinct','**An improved biochemical endpoint or reduced support use is not the same as a survival benefit.**',['The trial evaluated a defined metabolic-acidemia/AKI population.','Results should not be generalized to respiratory acidosis, ketoacidosis or exogenous acid poisoning.'],'**Choose buffering within an individualized organ-support plan.**',['Consider ventilation, sodium burden and urgent dialysis indications.','Do not delay treatment of shock or the acid source.'],[['Mortality','No significant 90-day reduction'],['KRT use','Lower in bicarbonate arm'],['Scope','Defined severe acidemia plus AKI cohort']],[BI],style='direct')

add('A patient with DKA has potassium 3.1 mmol/L before insulin. According to the 2024 consensus, which sequence is appropriate?', 'Begin potassium replacement and delay insulin until potassium exceeds 3.5 mmol/L',[
 ('Start insulin immediately and replace potassium only if it falls below 2.5','Insulin can rapidly worsen the already dangerous potassium deficit.'),('Withhold potassium because acidemia guarantees adequate total-body stores','Serum potassium does not reflect the substantial total-body deficit.'),('Use bicarbonate first to normalize potassium before considering replacement','This can further shift potassium intracellularly and is not the appropriate correction.')],
 'Potassium safety can precede insulin','**Insulin and correction of acidosis shift potassium into cells.**',['Patients with DKA often have depleted body stores even when initial serum levels are high.','The current consensus uses a greater-than-three-point-five threshold before insulin in this setting.'],'**Replace under a monitored protocol with renal-function assessment.**',['Continue fluids and other indicated stabilization.','Follow ECG, potassium and glucose frequently as insulin begins.'],[['Initial potassium','3.1 mmol/L'],['Immediate issue','Arrhythmia/weakness risk'],['Sequence','Potassium before insulin']],[DK])

add('A patient on an SGLT2 inhibitor has nausea, pH 7.22, bicarbonate 12 mmol/L, beta-hydroxybutyrate 5 mmol/L and glucose 168 mg/dL. Which diagnosis is most likely?', 'Euglycemic diabetic ketoacidosis',[
 ('Isolated starvation ketosis established by glucose alone','The severe acidosis, diabetes context and drug exposure require recognition of DKA.'),('Hyperosmolar hyperglycemic state','Marked hyperglycemia and hyperosmolality are not the defining pattern here.'),('Primary lactic acidosis with incidental ketonuria','Substantial measured beta-hydroxybutyrate provides direct evidence of ketoacidosis.')],
 'Glucose can be misleadingly modest','**SGLT2-associated DKA may occur without marked hyperglycemia.**',['Assess blood ketones and acid-base status in symptomatic patients.','A diabetes history satisfies the diabetes criterion even with glucose below two hundred.'],'**Stop the precipitating drug and treat ketoacidosis with fluids, insulin and appropriate dextrose/potassium.**',['Find fasting, infection or insulin-deficiency triggers.','Glucose normalization alone is not the resolution endpoint.'],[['Glucose','May be below 200 mg/dL'],['Ketones','Beta-hydroxybutyrate elevated'],['Treatment','Continue insulin safely with dextrose as needed']],[DK])

add('After DKA treatment, beta-hydroxybutyrate is 0.3 mmol/L, pH 7.34, bicarbonate 18 mmol/L and glucose 170 mg/dL. Chloride is elevated and the anion gap remains difficult to interpret. Which endpoint best supports resolution?', 'Ketone clearance with recovery of pH or bicarbonate, rather than anion gap alone',[
 ('Persistent urinary ketones necessarily require prolonged IV insulin','Urine acetoacetate can lag or rise as beta-hydroxybutyrate is metabolized.'),('Anion-gap closure is the only acceptable resolution criterion','Hyperchloremic acidosis and other gap influences make it unreliable alone.'),('Glucose below 200 alone proves DKA resolution','Acidosis and ketonemia may persist after glucose improves.')],
 'Measure the process being treated','**The consensus emphasizes plasma ketones below 0.6 mmol/L plus pH at least 7.3 or bicarbonate at least 18.**',['Glucose should ideally also be below two hundred.','The described values meet the biochemical recovery pattern.'],'**Arrange safe insulin transition with overlap and a prevention plan.**',['Evaluate ongoing intake and insulin requirements.','Do not mistake treatment-related hyperchloremia for persistent ketogenesis.'],[['Blood ketones','Direct recovery marker'],['Urine ketones','Can lag'],['Gap','Not the sole resolution endpoint']],[DK])

add('A septic patient has pH 7.49, PaCO2 25 mmHg and bicarbonate 19 mmol/L. The bicarbonate reduction is greater than expected for a purely acute respiratory alkalosis. Which combination is most plausible?', 'Respiratory alkalosis with metabolic acidosis',[
 ('Isolated acute respiratory alkalosis','The relatively large bicarbonate fall suggests an additional metabolic process.'),('Metabolic alkalosis with respiratory compensation','Both bicarbonate and CO2 changes oppose that interpretation.'),('Respiratory acidosis with metabolic compensation','CO2 is low rather than elevated.')],
 'Alkalemic pH does not exclude a clinically important acidosis','**A respiratory alkalosis can dominate the pH despite a metabolic acid burden.**',['Sepsis can increase respiratory drive and generate lactate simultaneously.','Assess the time course because chronic respiratory alkalosis produces more renal compensation than acute disease.'],'**Check lactate, gap and clinical perfusion rather than judging severity from pH alone.**',['Treat infection and source/perfusion abnormalities.','Repeat gas analysis when respiratory status changes.'],[['pH','Alkalemic'],['CO2','Low'],['Bicarbonate','Lower than acute compensation predicts']],[AB])
